// Populate accessToken and refreshToken environment variables from the login response
const response = pm.response.json();

if (response.accessToken && response.refreshToken) {
    pm.environment.set("accessToken", response.accessToken);
    pm.environment.set("refreshToken", response.refreshToken);

    console.log("Tokens saved to environment.");
} else {
    console.warn("accessToken/refreshToken not found in response body.");
}

pm.test("Login response contains tokens", function () {
    pm.expect(response).to.have.property("accessToken");
    pm.expect(response).to.have.property("refreshToken");
});

